def is_valid_simple_html_tags(s):
    import re
    tokens = re.findall(r'<[a-z]>|</[a-z]>', s)
    if len(''.join(tokens)) != len(s):
        return False
    stack = []
    for tok in tokens:
        if tok.startswith('</'):
            letter = tok[2]
            if not stack or stack.pop() != letter:
                return False
        else:
            stack.append(tok[1])
    return not stack

def is_valid_luhn_number(s):
    if len(s) < 2 or not s.isdigit():
        return False
    total = 0
    for i, ch in enumerate(reversed(s)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def is_valid_dashed_credit_card(s):
    import re
    if not re.fullmatch(r'\d{4}-\d{4}-\d{4}-\d{4}', s):
        return False
    digits = s.replace('-', '')
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
