def is_valid_isbn10(s):
    s = s.replace('-', '')
    if len(s) != 10:
        return False
    if not s[:9].isdigit():
        return False
    if not (s[9].isdigit() or s[9] == 'X'):
        return False
    total = 0
    for i, ch in enumerate(s):
        val = 10 if ch == 'X' else int(ch)
        total += val * (10 - i)
    return total % 11 == 0

def is_valid_isbn13(s):
    s = s.replace('-', '')
    if len(s) != 13 or not s.isdigit():
        return False
    total = 0
    for i, ch in enumerate(s):
        weight = 1 if i % 2 == 0 else 3
        total += int(ch) * weight
    return total % 10 == 0
